const ioFor=(module,validate)=>({module,validate,actor:()=>IE.ses('rayo_admin_user'),pricing:()=>PR(),
 load:async()=>{const r=await fetch(E.API_ROOT+`Load?module=${module}&_=`+Date.now(),{cache:'no-store',credentials:'omit',headers:{Accept:'application/json'}});if(!r.ok)throw Error(`دریافت ${module} از سرور: HTTP ${r.status}`);return E.unwrap(await r.json())},
 save:async doc=>{const r=await fetch(E.API_ROOT+`Save?module=${module}`,{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json; charset=utf-8',Accept:'application/json, text/plain, */*'},body:JSON.stringify(doc)});if(!r.ok)throw Error(`ذخیره روی سرور: HTTP ${r.status} ${(await r.text()).slice(0,200)}`)}});
