function lastCounts(){const m=new Map;for(const s of A(RAW().inventory?.stocktakes)){if(s.status!=='approved')continue;const d=E.D(s.date);for(const l of A(s.lines))if(l.actual!==null&&l.actual!==undefined&&l.actual!==''&&(!m.has(l.ingredientId)||m.get(l.ingredientId)<d))m.set(l.ingredientId,d)}return m}
