/* delete / archive items: zero-only count lines go first (inventory save), then the catalog (pricing save) */
async function runCleanup(btn,ids,label,{allowOpening=false,reason=''}={}){const onHand=onHandMap()||new Map(ids.map(x=>[x,1])),inv=RAW().inventory,zero=ids.filter(id=>{const p=MW.cleanupPlan(PR(),inv,id,{onHand,allowOpening});return p.action==='delete'&&(p.refs.zeroCounts>0||p.refs.withOpening)});
 const t=btn.innerHTML;btn.disabled=true;btn.innerHTML=P.ic('loader')+'ذخیره و تأیید روی سرور…';RT.icons();
 try{let z=null;if(zero.length){const r=await W.edit(ioInvC,{action:'CATALOG_ZERO_COUNT_LINES_REMOVED',details:{count:zero.length},mutate:(d,c)=>W.removeZeroCountLines(d,c,{ids:zero,opening:allowOpening,reason})});IC.attach({...RAW(),inventory:r.doc,source:'live'});z=r.out}
  const r2=await W.edit(ioPr,{action:'CATALOG_CLEANUP',details:{count:ids.length,label,...(reason?{reason}:{})},mutate:(d,c)=>MW.cleanupIngredients(d,c,{ids,inv:RAW().inventory,onHand:onHandMap()||onHand,allowOpening})});IC.attach({...RAW(),pricing:r2.doc,source:'live'});const o=r2.out;
  P.close();P.render();P.toast(`${fa(o.deleted.length)} قلم حذف و ${fa(o.archived.length)} قلم آرشیو شد${z?` (${fa(z.lines)} ردیف شمارش ${allowOpening?'':'صفر '}برداشته شد)`:''}${o.kept.length?' · '+fa(o.kept.length)+' قلم در رسپی فعال است یا موجودی دارد و دست نخورد':''}`,'check')}
 catch(e){P.toast(e.message||String(e),'alert-triangle');if(W.state.uncertain){P.close();P.render()}}finally{if(document.body.contains(btn)){btn.disabled=false;btn.innerHTML=t;RT.icons()}}}
const planWhy=p=>[p.refs.activeMenus.length?'در رسپی آیتم فعال: '+p.refs.activeMenus.slice(0,3).map(m=>esc(m.name)).join('، '):'',p.refs.activePrep.length?'در قلم آماده‌سازی فعال':'',Math.abs(p.refs.onHand||0)>1e-6?'موجودی دارد: '+fa(+Number(p.refs.onHand).toFixed(3)):'',p.refs.inactiveMenus.length?'آیتم غیرفعال: '+p.refs.inactiveMenus.slice(0,3).map(m=>esc(m.name)).join('، '):'',p.refs.prepared.length&&!p.refs.activePrep.length?'قلم آماده‌سازی غیرفعال':'',Object.keys(p.refs.history).length?'سابقهٔ انبار ('+Object.keys(p.refs.history).map(k=>({stocktakes:'شمارش با مقدار',stockReceipts:'ورود',inventoryMovements:'حرکت',wasteRecords:'ضایعات',beverageDailyControls:'نوشیدنی',purchaseInvoices:'فاکتور',salesPeriods:'فروش',consumptionRecords:'مصرف',openingBalances:'موجودی اولیه'})[k]||k).join('، ')+')':'',p.refs.recipeVersions?'نسخهٔ قبلی رسپی':'',p.refs.invoicePrices?'قیمت از فاکتور':'',p.refs.zeroCounts?fa(p.refs.zeroCounts)+' شمارش صفر (با قلم برداشته می‌شود)':'',p.refs.openingOnly&&!p.refs.withOpening?'فقط در شمارش افتتاحیه':''].filter(Boolean).join(' · ');
// delete one item from its form (owner / pricing access): delete, archive or refuse with the reason
function deleteItem(id){const i=A(PR()?.ingredients).find(x=>x.id===id),onHand=onHandMap();if(!i)return;if(!onHand)return P.toast('موجودی انبار محاسبه نشد؛ صفحه را دوباره بارگذاری کنید','alert-triangle');const own=P.owner(),p=MW.cleanupPlan(PR(),RAW().inventory,id,{onHand,allowOpening:own}),op=p.action==='delete'&&p.refs.withOpening;
 // same name elsewhere in the catalog: a hint that this is a duplicate
 const twins=A(PR()?.ingredients).filter(x=>x.id!==id&&!x.isArchived&&MW.ingredientUsage&&String(x.name).replace(/\s+/g,' ').trim()===String(i.name).replace(/\s+/g,' ').trim());
 form('pricing',{title:`حذف قلم «${esc(i.name)}»`,ok:p.action==='keep'?'بستن':p.action==='delete'?'حذف روی سرور':'آرشیو روی سرور',body:op?P.note(`<b>این قلم فقط در شمارش افتتاحیه آمده است</b> (${fa(p.refs.openingLines)} ردیف، جمع ${fa(+Number(p.refs.openingQty).toFixed(3))} ${esc(i.recipeUnit||'')}) و هیچ رسپی، ورود، فروش، ضایعات یا شمارش بعدی ندارد؛ معمولاً یعنی قلم تکراری یا اشتباه است.${twins.length?` قلم هم‌نام: ${twins.map(t=>esc(t.code||t.id)).join('، ')}.`:''} با حذف، ردیف افتتاحیه‌اش برداشته می‌شود (در سابقهٔ همان شمارش می‌ماند) و موجودی آن از انبار کم می‌شود؛ اگر این موجودی واقعاً مال قلم دیگری است، بعد برای آن قلم شمارش تازه ثبت کنید.`,'alert-triangle')+P.field('علت *','<input class="input" name="why" placeholder="مثلاً قلم تکراری؛ قلم اصلی کد …">'):p.action==='keep'?P.note('<b>این قلم حذف یا آرشیو نمی‌شود:</b> '+planWhy(p)+'. اول آن را از رسپی آیتم‌های فعال یا قلم آماده بردارید یا موجودی‌اش را با شمارش صفر کنید.','alert-triangle'):p.action==='delete'?P.note('این قلم هیچ سابقهٔ واقعی ندارد و <b>حذف</b> می‌شود'+(p.refs.zeroCounts?' (و '+fa(p.refs.zeroCounts)+' ردیف شمارش صفرش از شمارش‌ها برداشته می‌شود)':'')+'. نسخهٔ کامل ردیف در گزارش تغییرات می‌ماند و کدش دوباره داده نمی‌شود.','info'):P.note('<b>این قلم سابقه دارد و حذف فیزیکی نمی‌شود؛ آرشیو می‌شود:</b> '+planWhy(p)+'. غیرفعال و از همهٔ فهرست‌ها و فرم‌ها پنهان می‌شود و سابقه‌اش در گزارش‌ها می‌ماند. با فیلتر «آرشیو» پیداست.','archive'),
  onSave:(m,b)=>{if(p.action==='keep')return P.close();if(op){const why=P.$('[name=why]',m).value.trim();if(!why)throw Error('علت حذف لازم است');return runCleanup(b,[id],'one',{allowOpening:true,reason:why})}runCleanup(b,[id],'one')}})}
/* clean-up of unused items: delete when nothing refers to them, archive when only inactive menu items or history do */
const onHandMap=()=>{try{return new Map(E.positions(IC.state.M,E.CAL.today).map(r=>[r.id,r.qty]))}catch(_){return null}};
function cleanupForm(){const pr=PR(),inv=RAW().inventory,onHand=onHandMap();if(!onHand)return P.toast('موجودی انبار محاسبه نشد؛ صفحه را دوباره بارگذاری کنید','alert-triangle');const plans=A(pr?.ingredients).filter(i=>!i.isArchived).map(i=>({i,p:MW.cleanupPlan(pr,inv,i.id,{onHand})})).filter(o=>o.p.action!=='keep').sort((a,b)=>a.p.action.localeCompare(b.p.action)||String(a.i.name).localeCompare(String(b.i.name),'fa'));
 const why=planWhy;
 form('pricing',{title:'پاک‌سازی اقلام بدون استفاده',size:'wide',body:P.note('فقط اقلامی که در رسپی هیچ آیتم فعال و هیچ قلم آماده‌سازی فعالی نیستند و الان موجودی ندارند (قلم دارای موجودی را اول با شمارش یا ضایعات صفر کنید). <b>حذف</b> = هیچ‌جا به آن ارجاع نیست (نسخهٔ کامل ردیف در گزارش تغییرات می‌ماند و کدش دوباره داده نمی‌شود). <b>آرشیو</b> = سابقه دارد یا در آیتم غیرفعال است؛ غیرفعال و از فهرست‌ها پنهان می‌شود و با فیلتر «آرشیو» پیداست.','info')+
  (plans.length?`<label class="check" style="margin:8px 0"><input type="checkbox" id="cuAll">انتخاب همه</label><div class="table-wrap no-grid" style="max-height:52vh;overflow:auto"><table class="table no-grid"><thead><tr><th></th><th>کد</th><th>نام</th><th>گروه</th><th>اقدام</th><th>دلیل</th></tr></thead><tbody>${plans.map(({i,p})=>`<tr><td><input type="checkbox" name="cu" value="${esc(i.id)}"></td><td>${esc(i.code||'')}</td><td>${esc(i.name)}</td><td>${esc(i.category||'')}</td><td>${p.action==='delete'?P.b('حذف','danger',1):P.b('آرشیو','neutral',1)}</td><td><small>${why(p)||'—'}</small></td></tr>`).join('')}</tbody></table></div><p class="muted" id="cuN" style="margin-top:8px"></p>`:P.note('قلم بدون استفاده‌ای نیست.','check')),
  ok:'اجرا روی سرور',onMount:m=>{const n=()=>{const c=m.querySelectorAll('[name=cu]:checked'),pl=[...c].map(x=>plans.find(o=>o.i.id===x.value).p.action);P.$('#cuN',m)&&(P.$('#cuN',m).textContent=`${fa(pl.filter(a=>a==='delete').length)} حذف · ${fa(pl.filter(a=>a==='archive').length)} آرشیو`)};const all=P.$('#cuAll',m);if(all)all.onchange=()=>{m.querySelectorAll('[name=cu]').forEach(x=>x.checked=all.checked);n()};m.addEventListener('change',n);n()},
  onSave:(m,b)=>{const ids=[...m.querySelectorAll('[name=cu]:checked')].map(x=>x.value);if(!ids.length)return P.toast('قلمی انتخاب نشده است','alert-triangle');
   runCleanup(b,ids,'bulk')}})}

